class AttributeDocumenter(Documenter):
    """
    Documenter for attributes.
    """
    objtype = 'attribute'
    member_order = 0
    priority = 10

    @classmethod
    def can_document_member(cls, member: Any, membername: str, isattr: bool, parent: Any
                            ) -> bool:
        """Called to see if a member can be documented by this documenter."""
        return isattr

    def import_object(self, raiseerror: bool = False) -> bool:
        """Import the object given by *self.modname* and *self.objpath* and set
        it as *self.object*.

        Returns True if successful, False if an error occurred.
        """
        try:
            ret = super().import_object(raiseerror)
            if ret:
                # check if the object is an attribute
                if not inspect.isattribute(self.object):
                    return False
            return ret
        except ImportError as exc:
            if raiseerror:
                raise
            else:
                logger.warning(__('autodoc: failed to import attribute %r from module %r'),
                               self.fullname, self.modname, type='autodoc')
                return False

    def format_signature(self, **kwargs: Any) -> str:
        """Format the signature of the object.

        :return: the signature of the object
        """
        return ''

    def add_directive_header(self, sig: str) -> None:
        """Add the directive header and options to the generated content."""
        super().add_directive_header(sig)

        # add annotation
        if self.options.annotation is SUPPRESS or self.retann:
            pass
        elif self.options.annotation:
            self.add_line('   :annotation: %s' % self.options.annotation, '<autodoc>')
        else:
            # get the annotation from the object
            annotation = self.get_attr(self.object, '__annotations__', {})
            if annotation:
                for name, ann in annotation.items():
                    if name == self.object_name:
                        self.add_line('   :type: %s' % self.format_annotation(ann), '<autodoc>')
                        break
