    """
    Documenter for attributes.
    """
    objtype = 'attribute'
    member_order = 0
    priority = 10

    @classmethod
    def can_document_member(cls, member: Any, membername: str, isattr: bool, parent: Any
                           ) -> bool:
        return isattr

    def import_object(self, raiseerror: bool = False) -> bool:
        try:
            ret = super().import_object(raiseerror=True)
            if ret:
                # check the object is actually an attribute
                if not inspect.isattribute(self.object):
                    raise TypeError
        except ImportError as exc:
            if raiseerror:
                raise
            else:
                logger.warning(__('autodoc: failed to import attribute %r from module %r'),
                               self.object_name, self.modname, type='autodoc')
                return False
        except (AttributeError, TypeError):
            if raiseerror:
                raise
            else:
                return False

        return True

